/**
 * Screenshots for Help Center answers, keyed by entry id.
 *
 * help-shots.json is GENERATED by `npm run screenshots` -- edit the shot list in
 * scripts/help-screenshots/shots.mjs and re-run it, never the JSON by hand.
 */

import type { HelpShot } from "./help-types"
import raw from "./help-shots.json"

export const HELP_SHOTS: Record<string, HelpShot[]> = raw as Record<string, HelpShot[]>

export const shotsFor = (entryId: string): HelpShot[] => HELP_SHOTS[entryId] ?? []
